import DOMPurify from 'dompurify';
import { fitToCss, type AlignPolicy, type FitPolicy } from '@signdo/core';
import type { SigndoLang } from './types.js';

/** Widget prompt strings. Same three languages as the signer and the landing page. */
const PROMPT_TEXT: Record<SigndoLang, { heading: string; hint: string; link: string; code: string }> = {
  en: { heading: 'Scan to sign', hint: 'Point your phone camera at the code.', link: 'Open signing link', code: 'Code' },
  it: { heading: 'Scansiona per firmare', hint: 'Inquadra il codice con la fotocamera del telefono.', link: 'Apri il link per firmare', code: 'Codice' },
  pt: { heading: 'Aponte para assinar', hint: 'Aponte a câmera do celular para o código.', link: 'Abrir link de assinatura', code: 'Código' },
};

/**
 * Insert a signature into the customer's field at EXACT dimensions.
 *
 * The container is fixed at the field's declared pixel size and the image is
 * placed with `object-fit`, so the browser performs a single uniform scale.
 * There is no code path here that can set width and height independently — which
 * is the whole no-distortion guarantee, expressed as CSS (spec §13).
 */
export interface RenderOptions {
  container: HTMLElement;
  svg: string;
  width: number;
  height: number;
  fitPolicy?: FitPolicy;
  align?: AlignPolicy;
  /** Desired output format. `'png'` triggers client-side rasterisation. */
  format?: 'svg' | 'png';
}

export interface RenderResult {
  image: HTMLImageElement;
  /** The data URL actually set on the `<img>` — SVG data URL or PNG data URL. */
  dataUrl: string;
  /** The format of the rendered output. */
  format: 'svg' | 'png';
}

/**
 * Rasterise a sanitised SVG data URL to PNG via an off-screen canvas.
 *
 * The SVG must already be safe (DOMPurify-sanitised). The canvas draws at the
 * requested pixel dimensions — the browser's built-in SVG renderer handles
 * sub-pixel accuracy, and the PNG output is exactly `width x height` pixels.
 */
function svgToPng(svgDataUrl: string, width: number, height: number): Promise<string> {
  return new Promise((resolve, reject) => {
    const image = new Image();
    image.onload = () => {
      try {
        const canvas = document.createElement('canvas');
        canvas.width = width;
        canvas.height = height;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          reject(new Error('Signdo: canvas 2d context unavailable'));
          return;
        }
        ctx.drawImage(image, 0, 0, width, height);
        resolve(canvas.toDataURL('image/png'));
      } catch (error) {
        reject(error);
      } finally {
        URL.revokeObjectURL(image.src);
      }
    };
    image.onerror = () => reject(new Error('Signdo: failed to load SVG for PNG conversion'));
    // Use a blob URL to avoid data-URL length limits in some browsers.
    const blob = new Blob([svgDataUrl], { type: 'image/svg+xml;charset=utf-8' });
    image.src = URL.createObjectURL(blob);
  });
}

export async function renderSignature(options: RenderOptions): Promise<RenderResult> {
  const { container, width, height } = options;

  /**
   * DOMPurify as the SECOND layer (spec §17).
   *
   * The server already generates this SVG from validated numeric stroke data and
   * asserts it against an allowlist, so nothing attacker-controlled should be
   * here. This runs anyway, on a different implementation, so that a bug in our
   * emitter cannot become stored XSS inside a customer's page.
   */
  const clean = DOMPurify.sanitize(options.svg, {
    USE_PROFILES: { svg: true, svgFilters: false },
    FORBID_TAGS: ['script', 'foreignObject', 'image', 'use', 'style', 'a'],
    FORBID_ATTR: ['href', 'xlink:href', 'style', 'onload', 'onerror'],
  });

  container.classList.add('signdo-signature-field');
  container.style.width = `${width}px`;
  container.style.height = `${height}px`;
  container.style.position = 'relative';
  container.style.overflow = 'hidden';
  container.replaceChildren();

  const css = fitToCss(options.fitPolicy, options.align);
  const image = document.createElement('img');

  // A data: URL rather than innerHTML: the SVG renders as an image, in its own
  // sandbox, where script would not execute even if one survived both sanitizers.
  const svgDataUrl = `data:image/svg+xml;charset=utf-8,${encodeURIComponent(clean)}`;
  let dataUrl: string;
  let format: 'svg' | 'png';

  if (options.format === 'png') {
    dataUrl = await svgToPng(svgDataUrl, width, height);
    format = 'png';
  } else {
    dataUrl = svgDataUrl;
    format = 'svg';
  }

  image.src = dataUrl;
  image.alt = 'Handwritten signature';
  image.decoding = 'async';
  image.style.display = 'block';
  image.style.width = css.width;
  image.style.height = css.height;
  image.style.maxWidth = '100%';
  image.style.maxHeight = '100%';
  image.style.objectFit = css.objectFit;
  image.style.objectPosition = css.objectPosition;
  // Centre the box itself so fit-width / fit-height stay aligned in the field.
  image.style.margin = 'auto';
  image.style.position = 'absolute';
  image.style.inset = '0';

  container.appendChild(image);
  return { image, dataUrl, format };
}

/** Minimal QR + pairing-code prompt. Replaceable by the integrator via `renderPrompt`. */
export function renderPrompt(
  container: HTMLElement,
  options: { qrSvg: string; qrUrl: string; pairingCode: string; width: number; height: number; lang?: SigndoLang },
): void {
  const text = PROMPT_TEXT[options.lang ?? 'en'];
  container.classList.add('signdo-signature-field');
  container.style.width = `${options.width}px`;
  container.style.height = `${options.height}px`;
  container.replaceChildren();

  const wrapper = document.createElement('div');
  wrapper.setAttribute('role', 'group');
  wrapper.setAttribute('aria-label', text.heading);
  Object.assign(wrapper.style, {
    display: 'flex',
    alignItems: 'center',
    gap: '12px',
    width: '100%',
    height: '100%',
    boxSizing: 'border-box',
    padding: '8px',
    // Theme hooks, not hardcoded colors: the integrator's page decides what
    // its dark mode looks like. Fallbacks keep a bare page readable.
    border: '1px dashed var(--signdo-border, #c7c7c7)',
    borderRadius: '8px',
    font: '13px/1.4 system-ui, sans-serif',
    color: 'var(--signdo-text, #333)',
  });

  const qr = document.createElement('div');
  // The QR markup is generated server-side by the `qrcode` library from a URL we
  // constructed; sanitized anyway, on principle.
  qr.innerHTML = DOMPurify.sanitize(options.qrSvg, { USE_PROFILES: { svg: true } });
  const svg = qr.querySelector('svg');
  if (svg) {
    svg.style.width = `${Math.min(options.height - 16, 120)}px`;
    svg.style.height = 'auto';
    svg.style.display = 'block';
  }

  const textBlock = document.createElement('div');
  const heading = document.createElement('strong');
  heading.textContent = text.heading;

  const hint = document.createElement('div');
  hint.textContent = text.hint;
  hint.style.color = 'var(--signdo-muted, #666)';

  /**
   * Accessible alternative to the QR (spec §44): a link and a spoken-friendly
   * code. The code is a convenience handle only — the cryptographic token is
   * still what the server validates, so this does not weaken the pairing.
   */
  const link = document.createElement('a');
  link.href = options.qrUrl;
  link.textContent = text.link;
  link.rel = 'noopener';
  link.target = '_blank';
  link.style.color = 'var(--signdo-link, #0b57d0)';

  const code = document.createElement('div');
  code.textContent = `${text.code}: ${options.pairingCode}`;
  code.style.cssText = 'font-family:ui-monospace,monospace;letter-spacing:.05em;color:var(--signdo-muted, #666)';

  textBlock.append(heading, hint, link, code);
  wrapper.append(qr, textBlock);
  container.appendChild(wrapper);
}
