import type { TransactionEvent } from '@signdo/core';
import { Transport } from './transport.js';
import { renderPrompt, renderSignature } from './render.js';
import type {
  CreateFieldOptions,
  FieldEvent,
  FieldListener,
  SigndoConfig,
  SigndoLang,
  SignatureResult,
} from './types.js';

export type { CreateFieldOptions, SigndoConfig, SigndoLang, SignatureResult } from './types.js';

const SUPPORTED_LANGS: readonly SigndoLang[] = ['en', 'it', 'pt'];

/**
 * Config lang, then field lang override, then the host page's own language
 * signals, then English — the same fallback order as the landing page and
 * the signer itself, so a field with no explicit `lang` still matches
 * whatever language the integrator's page is already showing.
 */
function resolveLang(configLang: SigndoLang | undefined, fieldLang: SigndoLang | undefined): SigndoLang {
  if (fieldLang) return fieldLang;
  if (configLang) return configLang;

  const candidates = [document.documentElement.lang, ...(navigator.languages ?? []), navigator.language];
  for (const candidate of candidates) {
    const base = candidate?.toLowerCase().split('-')[0];
    if (base && (SUPPORTED_LANGS as readonly string[]).includes(base)) return base as SigndoLang;
  }
  return 'en';
}

const RECOVERY_PREFIX = 'signdo:tx:';

/**
 * API origin baked in at build time from VITE_SIGNDO_API_BASE (the Docker
 * build already exports it for every web app). This is what lets the CDN
 * bundle be used as a two-line snippet: key, application, nothing else.
 */
const DEFAULT_API_BASE: string = (import.meta.env?.VITE_SIGNDO_API_BASE as string | undefined) ?? '';

function resolveElement(target: string | HTMLElement): HTMLElement {
  const element = typeof target === 'string' ? document.querySelector<HTMLElement>(target) : target;
  if (!element) throw new Error(`Signdo: element not found: ${String(target)}`);
  return element;
}

/** Stable per tab. Binds a transaction to this browser session (spec §9). */
function browserSessionId(): string {
  const key = 'signdo:session';
  let value = sessionStorage.getItem(key);
  if (!value) {
    value = Array.from(crypto.getRandomValues(new Uint8Array(24)))
      .map((byte) => byte.toString(16).padStart(2, '0'))
      .join('');
    sessionStorage.setItem(key, value);
  }
  return value;
}

export class SignatureField {
  private transport: Transport | null = null;
  private readonly listeners = new Map<FieldEvent, Set<FieldListener>>();
  private readonly element: HTMLElement;
  private transactionId: string | null = null;
  private channelToken: string | null = null;
  /**
   * Signature ids already rendered. THE duplicate-delivery guard (spec §18):
   * events can arrive twice from SSE replay plus the polling fallback, and the
   * integration must still see exactly one completion.
   */
  private readonly applied = new Set<string>();
  private destroyed = false;
  /** Stored image element from the most recent render. */
  private currentImage: HTMLImageElement | null = null;
  /** Current container dimensions (may be changed by resize/scale). */
  private currentWidth: number;
  private currentHeight: number;

  constructor(
    /** Resolved by SigndoClient.requireConfig(): apiBase is always present here. */
    private readonly config: SigndoConfig & { apiBase: string },
    private readonly options: CreateFieldOptions,
  ) {
    this.element = resolveElement(options.element);
    this.currentWidth = options.width;
    this.currentHeight = options.height;
  }

  on(event: FieldEvent, listener: FieldListener): this {
    let set = this.listeners.get(event);
    if (!set) {
      set = new Set();
      this.listeners.set(event, set);
    }
    set.add(listener);
    return this;
  }

  off(event: FieldEvent, listener: FieldListener): this {
    this.listeners.get(event)?.delete(listener);
    return this;
  }

  private emit(event: FieldEvent, payload?: unknown): void {
    for (const listener of this.listeners.get(event) ?? []) {
      try {
        listener(payload);
      } catch (error) {
        // A throwing integration callback must not break the signing flow.
        console.error('[signdo] listener threw', error);
      }
    }
  }

  private api(path: string): string {
    return `${this.config.apiBase.replace(/\/$/, '')}${path}`;
  }

  /** Create the transaction and show the QR. Safe to call once per field. */
  async open(): Promise<void> {
    try {
      await this.openTransaction();
    } catch (failure) {
      const error = failure instanceof Error ? failure : new Error('Signdo: could not start signing');
      if (!this.destroyed) this.emit('error', error);
      throw error;
    }
  }

  private async openTransaction(): Promise<void> {
    if (this.destroyed) throw new Error('Signdo: field has been destroyed');

    // Recover an in-flight transaction after a desktop refresh (spec §21).
    if (await this.tryRecover()) return;

    const lang = resolveLang(this.config.lang, this.options.lang);

    const response = await fetch(this.api('/v1/signature-transactions'), {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        authorization: `Bearer ${this.config.publicKey}`,
        // Guards against a double-click or a retried request creating two QRs.
        'idempotency-key': `${browserSessionId()}:${this.options.fieldId ?? this.options.element}`,
      },
      body: JSON.stringify({
        applicationId: this.config.applicationId,
        field: {
          fieldId: this.options.fieldId,
          width: this.options.width,
          height: this.options.height,
          fitPolicy: this.options.fitPolicy ?? 'contain',
          align: this.options.align ?? 'center',
          format: this.options.format ?? 'svg',
        },
        browserSessionId: browserSessionId(),
        documentLabel: this.options.documentLabel,
        lang,
      }),
    });

    if (!response.ok) {
      throw new Error(`Signdo: could not start signing (${response.status})`);
    }

    const created = await response.json();

    // A replay (same idempotency key, transaction still live) answers 200 with
    // the ORIGINAL row and no credentials — by server design, a double-click
    // must never mint a second QR. For the page this is indistinguishable from
    // a fresh create except by the missing fields, so detect it here: drop the
    // stale recovery record and retry once with a one-off key. The retry is
    // what the person meant; the replay was our bookkeeping talking.
    if (!created.qrUrl || !created.pairingCode) {
      sessionStorage.removeItem(`${RECOVERY_PREFIX}${this.recoveryKey()}`);
      const retry = await fetch(this.api('/v1/signature-transactions'), {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          authorization: `Bearer ${this.config.publicKey}`,
          'idempotency-key': crypto.randomUUID(),
        },
        body: JSON.stringify({
          applicationId: this.config.applicationId,
          field: {
            fieldId: this.options.fieldId,
            width: this.options.width,
            height: this.options.height,
            fitPolicy: this.options.fitPolicy ?? 'contain',
            align: this.options.align ?? 'center',
            format: this.options.format ?? 'svg',
          },
          browserSessionId: browserSessionId(),
          documentLabel: this.options.documentLabel,
          lang,
        }),
      });
      if (!retry.ok) {
        throw new Error(`Signdo: could not restart signing (${retry.status})`);
      }
      Object.assign(created, await retry.json());
    }

    this.transactionId = created.id;
    this.channelToken = created.channelToken;

    sessionStorage.setItem(
      `${RECOVERY_PREFIX}${this.recoveryKey()}`,
      JSON.stringify({ id: created.id, channelToken: created.channelToken }),
    );

    renderPrompt(this.element, {
      qrSvg: created.qrSvg,
      qrUrl: created.qrUrl,
      pairingCode: created.pairingCode,
      width: this.options.width,
      height: this.options.height,
      lang,
    });

    this.emit('ready', { transactionId: created.id, qrUrl: created.qrUrl, pairingCode: created.pairingCode });
    this.listen();
  }

  private recoveryKey(): string {
    return `${this.options.fieldId ?? String(this.options.element)}`;
  }

  /**
   * Resume after a page refresh.
   *
   * Only resumes when the server says the transaction is still live or already
   * signed. A terminal transaction is discarded rather than re-shown, so a stale
   * tab cannot resurrect a cancelled signing session.
   */
  private async tryRecover(): Promise<boolean> {
    const stored = sessionStorage.getItem(`${RECOVERY_PREFIX}${this.recoveryKey()}`);
    if (!stored) return false;

    try {
      const { id, channelToken } = JSON.parse(stored) as { id: string; channelToken: string };
      const response = await fetch(
        this.api(`/v1/signature-transactions/${id}?channelToken=${encodeURIComponent(channelToken)}`),
      );
      if (!response.ok) throw new Error('not recoverable');

      const transaction = await response.json();
      if (['EXPIRED', 'CANCELLED', 'FAILED'].includes(transaction.status)) {
        throw new Error('terminal');
      }

      this.transactionId = id;
      this.channelToken = channelToken;

      if (transaction.signature) {
        await this.applySignature(transaction);
      } else {
        renderPrompt(this.element, {
          qrSvg: '',
          qrUrl: '',
          pairingCode: '',
          width: this.options.width,
          height: this.options.height,
          lang: resolveLang(this.config.lang, this.options.lang),
        });
      }

      this.listen();
      return true;
    } catch {
      sessionStorage.removeItem(`${RECOVERY_PREFIX}${this.recoveryKey()}`);
      return false;
    }
  }

  private listen(): void {
    if (!this.transactionId || !this.channelToken) return;

    this.transport = new Transport({
      apiBase: this.config.apiBase,
      transactionId: this.transactionId,
      channelToken: this.channelToken,
      onEvent: (event) => void this.onEvent(event),
      onError: (error) => this.emit('error', error),
    });
    this.transport.start();
  }

  private async onEvent(event: TransactionEvent): Promise<void> {
    switch (event.status) {
      case 'SCANNED':
        this.emit('scanned', event);
        break;
      case 'SIGNING':
        this.emit('signing', event);
        break;
      case 'SIGNED':
      case 'DELIVERING':
      case 'DELIVERED':
      case 'CONFIRMED':
        await this.fetchAndApply();
        break;
      case 'EXPIRED':
        this.emit('expired', event);
        this.transport?.close();
        break;
      case 'CANCELLED':
        this.emit('cancelled', event);
        this.transport?.close();
        break;
      default:
        break;
    }
  }

  private async fetchAndApply(): Promise<void> {
    if (!this.transactionId || !this.channelToken) return;
    const response = await fetch(
      this.api(
        `/v1/signature-transactions/${this.transactionId}?channelToken=${encodeURIComponent(this.channelToken)}`,
      ),
    );
    if (!response.ok) return;
    await this.applySignature(await response.json());
  }

  /**
   * Verify, render once, then confirm.
   *
   * Verification before DOM insertion (spec §19): the transaction id and field
   * must match what this field asked for, so a signature can never be rendered
   * into the wrong field even if an event were misrouted.
   */
  private async applySignature(transaction: any): Promise<void> {
    const signature = transaction.signature;
    if (!signature) return;

    if (transaction.id !== this.transactionId) return;
    if (transaction.field?.width !== this.options.width || transaction.field?.height !== this.options.height) {
      this.emit('error', new Error('Signdo: field geometry does not match this transaction'));
      return;
    }

    // Idempotent render: the same signature may arrive from SSE, from the poll
    // fallback, and from a reconnect replay.
    if (this.applied.has(signature.signatureId)) return;
    this.applied.add(signature.signatureId);

    const renderResult = await renderSignature({
      container: this.element,
      svg: signature.content,
      width: this.options.width,
      height: this.options.height,
      fitPolicy: this.options.fitPolicy,
      align: this.options.align,
      format: this.options.format,
    });

    this.currentImage = renderResult.image;

    const result: SignatureResult = {
      transactionId: transaction.id,
      status: transaction.status,
      signatureHash: signature.contentHash,
      format: renderResult.format,
      width: signature.intrinsicWidth,
      height: signature.intrinsicHeight,
      boundingBox: signature.boundingBox,
    };

    this.emit('completed', result);
    sessionStorage.removeItem(`${RECOVERY_PREFIX}${this.recoveryKey()}`);

    // Acknowledge delivery. Idempotent server-side, so a retry is harmless.
    if (transaction.status !== 'CONFIRMED') {
      await fetch(this.api(`/v1/signature-transactions/${transaction.id}/confirm`), {
        method: 'POST',
        headers: { 'content-type': 'application/json', 'x-signdo-channel-token': this.channelToken! },
        body: JSON.stringify({
          deliveryId: signature.signatureId,
          signatureHash: signature.contentHash,
        }),
      }).catch(() => {
        // The signature is already rendered; a failed ack is retried by the
        // server's own state machine and never loses the signature.
      });
    }
  }

  /**
   * Resize the signature field to new dimensions.
   *
   * The aspect ratio is always preserved: if only `width` is given, height is
   * computed from the original ratio; if only `height` is given, width is
   * computed; if both are given, the smaller scale factor is used (contain).
   * The signature image is scaled uniformly by CSS `object-fit: contain`.
   */
  resize(options: { width?: number; height?: number }): this {
    if (this.destroyed) throw new Error('Signdo: field has been destroyed');

    const originalWidth = this.options.width;
    const originalHeight = this.options.height;
    const aspectRatio = originalWidth / originalHeight;

    let newWidth: number;
    let newHeight: number;

    if (options.width != null && options.height != null) {
      // Both given: use the smaller scale factor to preserve aspect ratio.
      const scaleW = options.width / originalWidth;
      const scaleH = options.height / originalHeight;
      const s = Math.min(scaleW, scaleH);
      newWidth = originalWidth * s;
      newHeight = originalHeight * s;
    } else if (options.width != null) {
      newWidth = options.width;
      newHeight = options.width / aspectRatio;
    } else if (options.height != null) {
      newHeight = options.height;
      newWidth = options.height * aspectRatio;
    } else {
      return this;
    }

    if (!Number.isFinite(newWidth) || newWidth <= 0 || !Number.isFinite(newHeight) || newHeight <= 0) {
      throw new Error('Signdo: resize dimensions must be positive finite numbers');
    }

    this.currentWidth = newWidth;
    this.currentHeight = newHeight;
    this.element.style.width = `${newWidth}px`;
    this.element.style.height = `${newHeight}px`;
    return this;
  }

  /**
   * Scale the signature field by a uniform factor.
   *
   * A factor of 1.5 makes the field 50% larger in both dimensions while
   * preserving the aspect ratio.
   */
  scale(factor: number): this {
    if (this.destroyed) throw new Error('Signdo: field has been destroyed');
    if (!Number.isFinite(factor) || factor <= 0) {
      throw new Error('Signdo: scale factor must be a positive finite number');
    }
    return this.resize({
      width: this.options.width * factor,
      height: this.options.height * factor,
    });
  }

  async cancel(): Promise<void> {
    if (!this.transactionId || !this.channelToken) return;
    await fetch(this.api(`/v1/signature-transactions/${this.transactionId}/cancel`), {
      method: 'POST',
      headers: { 'x-signdo-channel-token': this.channelToken },
    }).catch(() => {});
    this.emit('cancelled', { transactionId: this.transactionId });
    this.destroy();
  }

  destroy(): void {
    this.destroyed = true;
    this.transport?.close();
    this.transport = null;
    this.listeners.clear();
  }
}

class SigndoClient {
  /** Resolved: init() guarantees apiBase is a string before anything reads it. */
  private config: (SigndoConfig & { apiBase: string }) | null = null;

  init(config: SigndoConfig): void {
    if (config.publicKey.startsWith('sk_')) {
      // The single most damaging integration mistake, caught loudly at init.
      throw new Error('Signdo: never use a secret key (sk_) in browser code. Use your pk_ key.');
    }
    // The CDN build bakes the API origin in at build time, so a customer's
    // snippet carries only their key and application. An explicit apiBase
    // still wins — self-hosters and staging builds point it wherever they
    // need — and an empty result from both is refused here, loudly, rather
    // than as a cryptic fetch failure on the first signature.
    const apiBase = config.apiBase ?? DEFAULT_API_BASE;
    if (!apiBase) {
      throw new Error('Signdo: apiBase is required when the bundle has no baked API origin');
    }
    this.config = { ...config, apiBase };
  }

  private requireConfig(): SigndoConfig & { apiBase: string } {
    if (!this.config) throw new Error('Signdo: call Signdo.init({ publicKey, applicationId }) first');
    return this.config;
  }

  createSignatureField(options: CreateFieldOptions): SignatureField {
    const field = new SignatureField(this.requireConfig(), options);
    // open() reports failures through the field's error event; an automatic
    // start has no caller to handle its rejected promise.
    if (options.autoOpen !== false) void field.open().catch(() => {});
    return field;
  }

  /** Promise-style alias: resolves when the signature has been rendered. */
  createSignature(options: CreateFieldOptions & { container?: string | HTMLElement }): Promise<SignatureResult> & {
    field: SignatureField;
  } {
    const field = new SignatureField(this.requireConfig(), {
      ...options,
      element: options.container ?? options.element,
    });

    const promise = new Promise<SignatureResult>((resolve, reject) => {
      field.on('completed', resolve);
      field.on('error', reject);
      field.on('expired', () => reject(new Error('Signdo: signing session expired')));
      field.on('cancelled', () => reject(new Error('Signdo: signing session cancelled')));
    });

    void field.open().catch(() => {});
    return Object.assign(promise, { field });
  }

  createField = (options: CreateFieldOptions): SignatureField => this.createSignatureField(options);
}

export const Signdo = new SigndoClient();
export default Signdo;

// NOTE: For IIFE builds (script tag usage), the global `Signdo` is set by the
// Vite IIFE footer (see vite.config.ts). The in-source `window.Signdo` assignment
// is intentionally removed because the IIFE wrapper `var Signdo = (function(e){...})({})`
// overwrites any `window.Signdo` set inside the function body.
// For ESM consumers (bundlers), the named/default exports are sufficient.
declare global {
  interface Window {
    Signdo: SigndoClient;
  }
}
